    12	
    13	public class GuestNotificationHandler implements EventHandler<ReservationConfirmedEvent> {
    14	    private final MessageService messageService;
    15	    private final RoomService roomService;
    16	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    17	
    18	    public GuestNotificationHandler(MessageService messageService, RoomService roomService) {
    19	        this.messageService = messageService;
    20	        this.roomService = roomService;
    21	    }
    22	
    23	    @Override
    24	    public void handle(ReservationConfirmedEvent event) {
    25	        Reservation r = event.getReservation();
    26	
    27	        String receipt = buildReceipt(r);
    28	        String subject = "Reserva confirmada - Pousada Maré Alta";
    29	        String body = String.format("""
    30	            Olá, %s!
    31	
    32	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    33	
    34	            %s
    35	
    36	            A entrada é a partir das 14h, e a saída, até as 12h.
    37	            Até breve!""", r.getGuestName(), receipt);
    38	
    39	        messageService.send(MessageChannel.EMAIL, r.getGuestEmail(), subject, body);
    40	    }
    41	
    42	    private String buildReceipt(Reservation r) {
    43	        RoomType roomType = roomService.findByNumber(r.getRoomNumber()).orElseThrow().getType();
    44	
    45	        StringBuilder receipt = new StringBuilder();
    46	        receipt.append(String.format("Comprovante de reserva nº %d\n", r.getId()));
    47	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", r.getGuestName(), formatCpf(r.getGuestCpf())));
    48	        receipt.append(String.format("Quarto: %d (%s)\n", r.getRoomNumber(), roomType));
    49	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
    50	            formatDate(r.getCheckIn()),
    51	            formatDate(r.getCheckOut()),
    52	            r.getNights(),
    53	            r.getNights() == 1 ? "diária" : "diárias"));
    54	        receipt.append(String.format("Diárias: %s\n", formatMoney(r.getSubtotal())));
    55	
    56	        if (r.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    57	            receipt.append(String.format("Desconto: %s\n", formatMoney(r.getDiscount())));
    58	        }
    59	
    60	        receipt.append(String.format("Total: %s", formatMoney(r.getTotal())));
    61	
    62	        return receipt.toString();
    63	    }
    64	
    65	    private String formatCpf(String cpf) {
    66	        if (cpf.length() == 11) {
    67	            return String.format("%s.%s.%s-%s",
    68	                cpf.substring(0, 3),
    69	                cpf.substring(3, 6),
    70	                cpf.substring(6, 9),
    71	                cpf.substring(9, 11));
    72	        }
    73	        return cpf;
    74	    }
    75	
    76	    private String formatDate(LocalDate date) {
    77	        return date.format(DATE_FORMATTER);
    78	    }
    79	
    80	    private String formatMoney(BigDecimal amount) {
    81	        return String.format("R$ %,.2f", amount).replace(",", "X").replace(".", ",").replace("X", ".");
    82	    }
    83	}
