     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.domain.*;
     4	import com.pousadamarealta.event.ReservationCancelledEvent;
     5	import com.pousadamarealta.event.ReservationConfirmedEvent;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.temporal.ChronoUnit;
    10	import java.util.*;
    11	import java.util.concurrent.atomic.AtomicLong;
    12	
    13	public class ReservationService {
    14	    private final AtomicLong nextId = new AtomicLong(1);
    15	    private final Map<Long, Reservation> reservations = new HashMap<>();
    16	    private final RoomService roomService;
    17	    private final PricingService pricingService;
    18	    private final EventService eventService;
    19	
    20	    public ReservationService(RoomService roomService, PricingService pricingService, EventService eventService) {
    21	        this.roomService = roomService;
    22	        this.pricingService = pricingService;
    23	        this.eventService = eventService;
    24	    }
    25	
    26	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                              LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    28	
    29	        Room room = roomService.findByNumber(roomNumber)
    30	            .orElseThrow(() -> new RoomNotFoundException());
    31	
    32	        if (guests < 1) {
    33	            throw new InvalidRequestException("At least one guest is required");
    34	        }
    35	
    36	        if (guests > room.getCapacity()) {
    37	            throw new CapacityExceededException();
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    45	            throw new RoomUnavailableException();
    46	        }
    47	
    48	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    49	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    50	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    51	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    52	
    53	        Reservation reservation = new Reservation(
    54	            nextId.getAndIncrement(),
    55	            roomNumber,
    56	            guestName,
    57	            guestEmail,
    58	            guestCpf,
    59	            checkIn,
    60	            checkOut,
    61	            guests,
    62	            ratePlan,
    63	            nights,
    64	            subtotal,
    65	            discount,
    66	            total
    67	        );
    68	
    69	        reservations.put(reservation.getId(), reservation);
    70	        return reservation;
    71	    }
    72	
    73	    public Optional<Reservation> findById(long id) {
    74	        return Optional.ofNullable(reservations.get(id));
    75	    }
    76	
    77	    public Reservation confirm(long id) {
    78	        Reservation reservation = findById(id)
    79	            .orElseThrow(() -> new ReservationNotFoundException());
    80	
    81	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    82	            throw new OperationNotAllowedException();
    83	        }
    84	
    85	        reservation.confirm();
    86	        eventService.publish(new ReservationConfirmedEvent(reservation));
    87	        return reservation;
    88	    }
    89	
    90	    public Reservation cancel(long id) {
    91	        Reservation reservation = findById(id)
    92	            .orElseThrow(() -> new ReservationNotFoundException());
    93	
    94	        if (reservation.getStatus() != ReservationStatus.PENDING
    95	            && reservation.getStatus() != ReservationStatus.CONFIRMED) {
    96	            throw new OperationNotAllowedException();
    97	        }
    98	
    99	        ReservationStatus previousStatus = reservation.getStatus();
   100	        reservation.cancel();
   101	        eventService.publish(new ReservationCancelledEvent(reservation, previousStatus));
   102	        return reservation;
   103	    }
   104	
   105	    public Reservation checkIn(long id) {
   106	        Reservation reservation = findById(id)
   107	            .orElseThrow(() -> new ReservationNotFoundException());
   108	
   109	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   110	            throw new OperationNotAllowedException();
   111	        }
   112	
   113	        reservation.checkIn();
   114	        return reservation;
   115	    }
   116	
   117	    public Reservation checkOut(long id) {
   118	        Reservation reservation = findById(id)
   119	            .orElseThrow(() -> new ReservationNotFoundException());
   120	
   121	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   122	            throw new OperationNotAllowedException();
   123	        }
   124	
   125	        reservation.checkOut();
   126	        return reservation;
   127	    }
   128	
   129	    public List<Reservation> getOccupancyForDate(LocalDate date) {
   130	        return reservations.values().stream()
   131	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   132	            .filter(Reservation::isPaid)
   133	            .filter(r -> r.occupiesDate(date))
   134	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
   135	            .toList();
   136	    }
   137	
   138	    public List<Reservation> getRevenueForMonth(int year, int month) {
   139	        return reservations.values().stream()
   140	            .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month)
   141	            .filter(r -> {
   142	                BigDecimal revenue = r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO);
   143	                return revenue.compareTo(BigDecimal.ZERO) > 0;
   144	            })
   145	            .sorted(Comparator.comparing(Reservation::getCheckIn)
   146	                .thenComparingLong(Reservation::getId))
   147	            .toList();
   148	    }
   149	
   150	    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   151	        return reservations.values().stream()
   152	            .filter(r -> r.getRoomNumber() == roomNumber)
   153	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   154	            .noneMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   155	    }
   156	
   157	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   158	        return !end1.isBefore(start2) && !start1.isAfter(end2.minusDays(1))
   159	            && !end2.isBefore(start1) && !start2.isAfter(end1.minusDays(1));
   160	    }
   161	
   162	    public static class RoomNotFoundException extends RuntimeException {}
   163	    public static class ReservationNotFoundException extends RuntimeException {}
   164	    public static class InvalidRequestException extends RuntimeException {
   165	        public InvalidRequestException(String message) {
   166	            super(message);
   167	        }
   168	    }
   169	    public static class CapacityExceededException extends RuntimeException {}
   170	    public static class RoomUnavailableException extends RuntimeException {}
   171	    public static class OperationNotAllowedException extends RuntimeException {}
   172	}
