    23	    @Override
    24	    public void handle(ReservationConfirmedEvent event) {
    25	        Reservation r = event.getReservation();
    26	
    27	        String receipt = buildReceipt(r);
    28	        String subject = "Reserva confirmada - Pousada Maré Alta";
    29	        String body = String.format("""
    30	            Olá, %s!
    31	
    32	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    33	
    34	            %s
    35	
    36	            A entrada é a partir das 14h, e a saída, até as 12h.
    37	            Até breve!""", r.getGuestName(), receipt);
