    42	    private String buildReceipt(Reservation r) {
    43	        RoomType roomType = roomService.findByNumber(r.getRoomNumber()).orElseThrow().getType();
    44	
    45	        StringBuilder receipt = new StringBuilder();
    46	        receipt.append(String.format("Comprovante de reserva nº %d\n", r.getId()));
    47	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", r.getGuestName(), formatCpf(r.getGuestCpf())));
    48	        receipt.append(String.format("Quarto: %d (%s)\n", r.getRoomNumber(), roomType));
    49	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
    50	            formatDate(r.getCheckIn()),
    51	            formatDate(r.getCheckOut()),
    52	            r.getNights(),
    53	            r.getNights() == 1 ? "diária" : "diárias"));
    54	        receipt.append(String.format("Diárias: %s\n", formatMoney(r.getSubtotal())));
    55	
    56	        if (r.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    57	            receipt.append(String.format("Desconto: %s\n", formatMoney(r.getDiscount())));
    58	        }
    59	
    60	        receipt.append(String.format("Total: %s", formatMoney(r.getTotal())));
    61	
    62	        return receipt.toString();
    63	    }
    64	
