    11	public class EventService {
    12	    private final Map<Class<? extends ReservationEvent>, List<EventHandler<? extends ReservationEvent>>> handlers = new HashMap<>();
    13	
    14	    public <T extends ReservationEvent> void register(Class<T> eventType, EventHandler<T> handler) {
    15	        handlers.computeIfAbsent(eventType, k -> new ArrayList<>()).add(handler);
    16	    }
    17	
    18	    @SuppressWarnings("unchecked")
    19	    public <T extends ReservationEvent> void publish(T event) {
    20	        List<EventHandler<? extends ReservationEvent>> eventHandlers = handlers.get(event.getClass());
    21	        if (eventHandlers != null) {
    22	            for (EventHandler<? extends ReservationEvent> handler : eventHandlers) {
    23	                ((EventHandler<T>) handler).handle(event);
    24	            }
    25	        }
    26	    }
    27	}
