    10	import java.util.*;
    11	import java.util.concurrent.atomic.AtomicLong;
    12	
    13	public class ReservationService {
    14	    private final AtomicLong nextId = new AtomicLong(1);
    15	    private final Map<Long, Reservation> reservations = new HashMap<>();
    16	    private final RoomService roomService;
    17	    private final PricingService pricingService;
    18	    private final EventService eventService;
    19	
    20	    public ReservationService(RoomService roomService, PricingService pricingService, EventService eventService) {
    21	        this.roomService = roomService;
    22	        this.pricingService = pricingService;
    23	        this.eventService = eventService;
    24	    }
    25	
    26	    public Reservation create(int roomNumber, String guestName, String guestEmail, String guestCpf,
    27	                              LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    28	
    29	        Room room = roomService.findByNumber(roomNumber)
    30	            .orElseThrow(() -> new RoomNotFoundException());
    31	
    32	        if (guests < 1) {
    33	            throw new InvalidRequestException("At least one guest is required");
    34	        }
    35	
    36	        if (guests > room.getCapacity()) {
    37	            throw new CapacityExceededException();
    38	        }
    39	
    40	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    41	            throw new InvalidRequestException("Check-out must be after check-in");
    42	        }
    43	
    44	        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
    45	            throw new RoomUnavailableException();
    46	        }
    47	
    48	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    49	        BigDecimal subtotal = pricingService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    50	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    51	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    52	
    53	        Reservation reservation = new Reservation(
    54	            nextId.getAndIncrement(),
    55	            roomNumber,
    56	            guestName,
    57	            guestEmail,
    58	            guestCpf,
    59	            checkIn,
    60	            checkOut,
    61	            guests,
    62	            ratePlan,
    63	            nights,
    64	            subtotal,
    65	            discount,
    66	            total
    67	        );
    68	
    69	        reservations.put(reservation.getId(), reservation);
    70	        return reservation;
    71	    }
