    73	    public Optional<Reservation> findById(long id) {
    74	        return Optional.ofNullable(reservations.get(id));
    75	    }
    76	
    77	    public Reservation confirm(long id) {
    78	        Reservation reservation = findById(id)
    79	            .orElseThrow(() -> new ReservationNotFoundException());
    80	
    81	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    82	            throw new OperationNotAllowedException();
    83	        }
    84	
    85	        reservation.confirm();
    86	        eventService.publish(new ReservationConfirmedEvent(reservation));
    87	        return reservation;
    88	    }
    89	
    90	    public Reservation cancel(long id) {
    91	        Reservation reservation = findById(id)
    92	            .orElseThrow(() -> new ReservationNotFoundException());
    93	
    94	        if (reservation.getStatus() != ReservationStatus.PENDING
    95	            && reservation.getStatus() != ReservationStatus.CONFIRMED) {
    96	            throw new OperationNotAllowedException();
    97	        }
    98	
    99	        ReservationStatus previousStatus = reservation.getStatus();
   100	        reservation.cancel();
   101	        eventService.publish(new ReservationCancelledEvent(reservation, previousStatus));
   102	        return reservation;
   103	    }
