   105	    public Reservation checkIn(long id) {
   106	        Reservation reservation = findById(id)
   107	            .orElseThrow(() -> new ReservationNotFoundException());
   108	
   109	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   110	            throw new OperationNotAllowedException();
   111	        }
   112	
   113	        reservation.checkIn();
   114	        return reservation;
   115	    }
