   117	    public Reservation checkOut(long id) {
   118	        Reservation reservation = findById(id)
   119	            .orElseThrow(() -> new ReservationNotFoundException());
   120	
   121	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   122	            throw new OperationNotAllowedException();
   123	        }
   124	
   125	        reservation.checkOut();
   126	        return reservation;
   127	    }
