   129	    public List<Reservation> getOccupancyForDate(LocalDate date) {
   130	        return reservations.values().stream()
   131	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   132	            .filter(Reservation::isPaid)
   133	            .filter(r -> r.occupiesDate(date))
   134	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
   135	            .toList();
   136	    }
   137	
   138	    public List<Reservation> getRevenueForMonth(int year, int month) {
   139	        return reservations.values().stream()
   140	            .filter(r -> r.getCheckIn().getYear() == year && r.getCheckIn().getMonthValue() == month)
   141	            .filter(r -> {
   142	                BigDecimal revenue = r.getAmountPaid().subtract(r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO);
   143	                return revenue.compareTo(BigDecimal.ZERO) > 0;
   144	            })
   145	            .sorted(Comparator.comparing(Reservation::getCheckIn)
   146	                .thenComparingLong(Reservation::getId))
   147	            .toList();
   148	    }
