   150	    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   151	        return reservations.values().stream()
   152	            .filter(r -> r.getRoomNumber() == roomNumber)
   153	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED)
   154	            .noneMatch(r -> datesOverlap(r.getCheckIn(), r.getCheckOut(), checkIn, checkOut));
   155	    }
   156	
   157	    private boolean datesOverlap(LocalDate start1, LocalDate end1, LocalDate start2, LocalDate end2) {
   158	        return !end1.isBefore(start2) && !start1.isAfter(end2.minusDays(1))
   159	            && !end2.isBefore(start1) && !start2.isAfter(end1.minusDays(1));
   160	    }
