   155	package com.pousadamarealta.service;
   156	
   157	import com.pousadamarealta.domain.RatePlan;
   158	
   159	import java.math.BigDecimal;
   160	import java.math.RoundingMode;
   161	import java.time.LocalDate;
   162	
   163	public class PricingService {
   164	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
   165	
   166	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
   167	        if (isHighSeason(date)) {
   168	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
   169	        }
   170	        return baseRate;
   171	    }
   172	
   173	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
   174	        BigDecimal subtotal = BigDecimal.ZERO;
   175	        LocalDate current = checkIn;
   176	
   177	        while (current.isBefore(checkOut)) {
   178	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
   179	            subtotal = subtotal.add(nightPrice);
   180	            current = current.plusDays(1);
   181	        }
   182	
   183	        return round(subtotal);
   184	    }
   185	
   186	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
   187	        if (ratePlan.getDiscountRate().compareTo(BigDecimal.ZERO) == 0) {
   188	            return BigDecimal.ZERO;
   189	        }
   190	        return round(subtotal.multiply(ratePlan.getDiscountRate()));
   191	    }
   192	
   193	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
   194	        return round(subtotal.subtract(discount));
   195	    }
   196	
   197	    private boolean isHighSeason(LocalDate date) {
   198	        int month = date.getMonthValue();
   199	        int day = date.getDayOfMonth();
   200	
   201	        if (month == 12 && day >= 15) {
   202	            return true;
   203	        }
   204	
   205	        if (month == 1 || month == 2) {
   206	            return true;
   207	        }
   208	
   209	        if (month == 7) {
   210	            return true;
   211	        }
   212	
   213	        return false;
   214	    }
   215	
   216	    private BigDecimal round(BigDecimal value) {
   217	        return value.setScale(2, RoundingMode.HALF_EVEN);
   218	    }
   219	}
