   413	
   414	        StringBuilder csv = new StringBuilder();
   415	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   416	
   417	        BigDecimal total = BigDecimal.ZERO;
   418	
   419	        for (Reservation r : revenueReservations) {
   420	            BigDecimal revenue = r.getAmountPaid().subtract(
   421	                r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO
   422	            );
   423	            total = total.add(revenue);
   424	
   425	            csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
   426	                r.getId(),
   427	                r.getRoomNumber(),
   428	                r.getCheckIn(),
   429	                r.getCheckOut(),
   430	                r.getStatus(),
   431	                formatCsvNumber(revenue)
   432	            ));
   433	        }
   434	
   435	        csv.append(String.format("total,%s", formatCsvNumber(total)));
   436	
   437	        return csv.toString();
   438	    }
